parameters.jsonBody:
={{ (() => {
    const AIMFOX_REPLY_NODE = '[79+72+51+8+57] Compute derived values';
  const AIMFOX_LEAD_NODE = 'GET lead info Aimfox';

  const LUSHA_ENRICH_NODE = 'Lusha Enrichment';

  const safe = (fn, fallback = '') => {
    try {
      const value = fn();
      return value === undefined || value === null ? fallback : value;
    } catch (e) {
      return fallback;
    }
  };

  const pick = (...sources) => {
    for (const fn of sources) {
      try {
        const v = fn();
        if (v !== undefined && v !== null && v !== '') return v;
      } catch (e) {}
    }
    return '';
  };

  const str = (value) => {
    if (value === undefined || value === null) return '';
    return String(value);
  };

  const nodeJson = (nodeName, fallback = {}) => {
    return safe(() => {
      const node = $(nodeName);
      if (node.isExecuted === false) return fallback;
      return node.first().json ?? fallback;
    }, fallback);
  };

  const unwrapN8nPayload = (raw) => {
    if (!raw) return {};
    if (Array.isArray(raw)) return raw[0] || {};
    if (Array.isArray(raw.body)) return raw.body[0] || {};
    if (raw.body?.event) return raw.body;
    if (Array.isArray(raw.data)) return raw.data[0] || {};
    return raw;
  };

  const toGoogleSheetsDateSerial = (value) => {
    if (value === undefined || value === null || value === '') return null;

    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return null;

    // Google Sheets serial date:
    // 1970-01-01 = 25569.
    return Math.floor(d.getTime() / 86400000) + 25569;
  };

  const makeCell = (value, index) => {
    // Column index 8 = LEAD RECEIVED.
    // Send it as a real Google Sheets date, not as text.
    if (index === 8) {
      const serial = toGoogleSheetsDateSerial(value);

      if (serial === null) {
        return {
          userEnteredValue: {
            stringValue: ''
          }
        };
      }

      return {
        userEnteredValue: {
          numberValue: serial
        },
        userEnteredFormat: {
          numberFormat: {
            type: 'DATE',
            pattern: 'mm/dd/yyyy'
          }
        }
      };
    }

    return {
      userEnteredValue: {
        stringValue: str(value)
      }
    };
  };

  const getDomainFromEmail = (email) => {
    if (!email || typeof email !== 'string' || !email.includes('@')) return '';
    return email.split('@').pop().trim().toLowerCase();
  };

  const normalizeDomain = (domain) => {
    if (!domain || typeof domain !== 'string') return '';
    return domain
      .replace(/^https?:\/\//i, '')
      .replace(/^www\./i, '')
      .replace(/\/.*$/, '')
      .trim()
      .toLowerCase();
  };

  const linkedinFromPublicId = (publicId) => {
    if (!publicId) return '';
    return `https://www.linkedin.com/in/${publicId}`;
  };

  const companyLinkedinFromUniversalName = (universalName) => {
    if (!universalName) return '';
    return `https://www.linkedin.com/company/${universalName}`;
  };

  const countryFromLocation = (locationName) => {
    if (!locationName || typeof locationName !== 'string') return '';
    const parts = locationName.split(',').map(p => p.trim()).filter(Boolean);
    return parts.length ? parts[parts.length - 1] : '';
  };

  const getPhoneValue = (phones) => {
    if (!Array.isArray(phones) || phones.length === 0) return '';

    const first = phones[0];

    if (typeof first === 'string') return first;

    return (
      first.number ||
      first.phone ||
      first.value ||
      first.raw ||
      ''
    );
  };

  const getLabelNames = (labels) => {
    if (!Array.isArray(labels)) return [];

    return labels
      .map(label => typeof label === 'string' ? label : label?.name)
      .filter(Boolean);
  };

  const qualificationFromLabels = (labels) => {
    const normalized = getLabelNames(labels)
      .map(v => String(v).trim().toLowerCase());

    if (normalized.includes('mql')) return 'MQL';
    if (normalized.includes('interested')) return 'MQL';
    if (normalized.includes('premql')) return 'preMQL';
    if (normalized.includes('pre-mql')) return 'preMQL';

    return '';
  };

  const normalizeRawAimfoxWebhook = (root) => {
    const event = root.event || {};
    const campaign = event.campaign || {};
    const target = event.target || {};
    const account = event.account || {};
    const workspace = root.workspace || {};

    const flowId = event.flow_id ?? null;
    const templateId = event.template_id ?? null;

    const flows = campaign.flows || [];
    const flowRow = flows.find(f => f.id === flowId) || {};
    const templates = flowRow.flow_message_templates || [];

    const exactTemplate = templates.find(t =>
      t.id === templateId ||
      t.template_id === templateId
    );

    const originalIdMatches = templates
      .map((t, index) => ({ ...t, _order: index + 1 }))
      .filter(t => t.original_id === templateId);

    const sequenceStepRow =
      exactTemplate
        ? { ...exactTemplate, _order: templates.indexOf(exactTemplate) + 1 }
        : originalIdMatches.length === 1
          ? originalIdMatches[0]
          : {};

    return {
      source: 'aimfox',

      reply_event_id: root.id ?? null,
      event_type: root.event_type ?? null,

      reply_message: event.message ?? '',
      reply_date: event.timestamp ?? root.timestamp ?? null,

      target_urn: event.target_urn ?? target.urn ?? null,
      target_id: target.id ?? null,
      target_public_identifier: target.public_identifier ?? null,
      target_first_name: target.first_name ?? null,
      target_last_name: target.last_name ?? null,
      target_full_name: [target.first_name, target.last_name].filter(Boolean).join(' '),
      target_email: target.email ?? null,

      account_id: account.id ?? null,
      account_public_identifier: account.public_identifier ?? null,
      account_first_name: account.first_name ?? null,
      account_last_name: account.last_name ?? null,

      campaign_id: campaign.id ?? null,
      campaign_name: campaign.name ?? null,
      campaign_state: campaign.state ?? null,
      campaign_type: campaign.type ?? null,
      outreach_type: campaign.outreach_type ?? null,

      workspace_id: workspace.id ?? null,
      workspace_name: workspace.name ?? null,

      flow_id: flowId,
      flow_type: event.flow_type ?? flowRow.type ?? null,
      flow_name: flowRow.name ?? null,

      template_id: templateId,

      sequence_step_id: templateId,
      sequence_step_order: sequenceStepRow._order ?? null,
      sequence_step_delay_hours: sequenceStepRow.delay ?? null,
      sequence_step_message: sequenceStepRow.message ?? null,
      sequence_step_match_ambiguous: !exactTemplate && originalIdMatches.length > 1,

      // Not available from a plain Aimfox reply webhook unless calculated earlier.
      first_email_date: null,
      response_time_hours: null,
      response_time_bucket: null,

      subject: '',

      declined: event.metadata?.declined ?? null,

      linkedin_profile_url: target.public_identifier
        ? linkedinFromPublicId(target.public_identifier)
        : '',
    };
  };

  const normalizeAimfoxReply = () => {
    let raw = unwrapN8nPayload(nodeJson(AIMFOX_REPLY_NODE, {}));

    if (
      raw.source === 'aimfox' ||
      raw.reply_event_id ||
      raw.reply_message ||
      raw.target_full_name ||
      raw.campaign_name
    ) {
      return raw;
    }

    if (raw.aimfox) return raw.aimfox;
    if (raw.data && !Array.isArray(raw.data)) return raw.data;

    if (raw.event || raw.event_type) {
      return normalizeRawAimfoxWebhook(raw);
    }

    return raw;
  };

  const normalizeAimfoxLead = () => {
    const rawRoot = unwrapN8nPayload(nodeJson(AIMFOX_LEAD_NODE, {}));

    const lead =
      rawRoot.lead ||
      rawRoot.data?.lead ||
      rawRoot.data ||
      rawRoot;

    const currentExperience =
      Array.isArray(lead.current_experience) && lead.current_experience.length
        ? lead.current_experience[0]
        : {};

    const currentCompany = currentExperience.company || {};

    const locationName = pick(
      () => currentExperience.location?.name,
      () => lead.location?.name,
    );

    const labelNames = getLabelNames(lead.labels);

    return {
      lead_id: lead.id ?? null,
      lead_urn: lead.urn ?? null,

      first_name: lead.first_name ?? null,
      last_name: lead.last_name ?? null,
      full_name: lead.full_name ?? null,

      occupation: lead.occupation ?? null,

      job_title: currentExperience.job_title ?? null,
      employment_type: currentExperience.employment_type?.name ?? null,

      company_name: currentCompany.name ?? null,
      company_urn: currentCompany.urn ?? null,
      company_universal_name: currentCompany.universal_name ?? null,
      company_linkedin_url: currentCompany.universal_name
        ? companyLinkedinFromUniversalName(currentCompany.universal_name)
        : '',

      location: locationName,
      country: countryFromLocation(locationName),

      linkedin_public_identifier: lead.public_identifier ?? null,
      linkedin_profile_url: lead.public_identifier
        ? linkedinFromPublicId(lead.public_identifier)
        : '',

      picture_url: lead.picture_url ?? null,

      phones: lead.phones || [],
      phone_number: getPhoneValue(lead.phones),

      labels: labelNames,
      qualification: qualificationFromLabels(lead.labels),

      connections: lead.connections ?? null,
      followers: lead.followers ?? null,
      verified: lead.verified ?? null,
      premium: lead.premium ?? null,

      origin_campaign_id: lead.origins?.[0]?.id ?? null,
      origin_campaign_name: lead.origins?.[0]?.name ?? null,

      skills: Array.isArray(lead.skills)
        ? lead.skills.map(s => s.name).filter(Boolean)
        : [],
    };
  };

  const normalizeLushaEnrichment = () => {
    const rawRoot = unwrapN8nPayload(nodeJson(LUSHA_ENRICH_NODE, {}));

    const body = rawRoot.body || rawRoot;

    const result =
      body.results?.[0] ||
      rawRoot.results?.[0] ||
      rawRoot.data?.results?.[0] ||
      rawRoot.data?.[0] ||
      {};

    const emailRow =
      Array.isArray(result.emails) && result.emails.length
        ? result.emails.find(e => e.type === 'work') || result.emails[0]
        : {};

    const phoneRow =
      Array.isArray(result.phones) && result.phones.length
        ? result.phones.find(p => p.doNotCall === false) || result.phones[0]
        : {};

    return {
      id: result.id ?? null,

      first_name: result.firstName ?? null,
      last_name: result.lastName ?? null,
      full_name: result.fullName ?? null,

      job_title: result.jobTitle?.title ?? null,
      job_departments: Array.isArray(result.jobTitle?.departments)
        ? result.jobTitle.departments.join(', ')
        : '',
      seniority: result.jobTitle?.seniority ?? null,

      company_id: result.company?.id ?? null,
      company_name: result.company?.name ?? null,
      company_domain: normalizeDomain(result.company?.domain),
      company_industry: result.company?.industry ?? null,

      country: result.location?.country ?? null,
      country_iso2: result.location?.countryIso2 ?? null,
      continent: result.location?.continent ?? null,
      is_eu_contact: result.location?.isEuContact ?? null,

      linkedin_url: result.socialLinks?.linkedin ?? null,

      email: emailRow.email ?? null,
      email_type: emailRow.type ?? null,
      email_confidence: emailRow.confidence ?? null,
      email_update_date: emailRow.updateDate ?? null,

      phone_number: phoneRow.number ?? null,
      phone_type: phoneRow.type ?? null,
      phone_do_not_call: phoneRow.doNotCall ?? null,
      phone_update_date: phoneRow.updateDate ?? null,

      update_date: result.updateDate ?? null,

      has_data: Boolean(
        result.id ||
        result.fullName ||
        emailRow.email ||
        phoneRow.number ||
        result.company?.name
      ),
    };
  };

  const aimfoxReply = normalizeAimfoxReply();
  const aimfoxLead = normalizeAimfoxLead();
  const lusha = normalizeLushaEnrichment();

  // Optional fallback enrichment nodes from the old flow.
  // These are fallback only. If they do not exist or were not executed, fields stay empty.
  const aiRaw = nodeJson('[286] Parse AI output + set phone', {});
  const ai = aiRaw.ai || aiRaw || {};

  const lushaRaw = nodeJson('[287] Set phone from Lusha', {});
  const lushaExecuted = safe(() => $('[287] Set phone from Lusha').isExecuted, false);

  const snovRaw = nodeJson('[226+227+228] Pick Snovio output body', {});
  const snovProspect = safe(() => snovRaw.snovio_body?.data?.[0], {});

  const sheet = safe(
    () => $json.sheets.find(sheet => sheet.properties?.title === 'Leads'),
    null
  );

  if (!sheet) {
    throw new Error('Sheet "Leads" not found');
  }

  const table = safe(
    () =>
      (sheet.tables || []).find(table => table.name === 'Leads') ||
      (sheet.tables || []).find(table => table.name === 'Table3') ||
      (sheet.tables || [])[0],
    null
  );

  if (!table) {
    throw new Error('No table found inside sheet "Leads"');
  }

  const fullName = pick(
    () => aimfoxLead.full_name,
    () => lusha.full_name,
    () => aimfoxReply.target_full_name,
    () => `${aimfoxLead.first_name || ''} ${aimfoxLead.last_name || ''}`.trim(),
    () => `${lusha.first_name || ''} ${lusha.last_name || ''}`.trim(),
    () => `${aimfoxReply.target_first_name || ''} ${aimfoxReply.target_last_name || ''}`.trim(),
    () => `${snovProspect.firstName || ''} ${snovProspect.lastName || ''}`.trim(),
    () => `${ai.first_name || ''} ${ai.last_name || ''}`.trim(),
  );

  const jobTitle = pick(
    () => aimfoxLead.job_title,
    () => lusha.job_title,
    () => aimfoxLead.occupation,
    () => ai.lead_position,
    () => ai.job_title,
    () => snovProspect.currentJob?.[0]?.position,
  );

  const email = pick(
    () => lusha.email,
    () => aimfoxReply.target_email,
    () => ai.email,
    () => ai.lead_email,
    () => snovProspect.emails?.[0]?.email,
  );

  const phoneNumber = pick(
    // Prefer Lusha only if not marked DNC.
    () => lusha.phone_do_not_call === false ? lusha.phone_number : '',
    () => aimfoxLead.phone_number,
    // Fallback: keep Lusha phone if DNC flag was absent/null, but not if explicitly true.
    () => lusha.phone_do_not_call !== true ? lusha.phone_number : '',
    () => lushaExecuted ? lushaRaw.phoneNumber : '',
    () => aiRaw.phoneNumber,
    () => ai.phoneNumber,
    () => ai.phone,
  );

  const phoneSource = pick(
    () => lusha.phone_number && lusha.phone_do_not_call === false ? 'Lusha' : '',
    () => aimfoxLead.phone_number ? 'Aimfox Lead' : '',
    () => lusha.phone_number && lusha.phone_do_not_call !== true ? 'Lusha' : '',
    () => lushaExecuted ? lushaRaw.phoneSource : '',
    () => aiRaw.phoneSource,
    () => ai.phoneSource,
  );

  const companyName = pick(
    () => aimfoxLead.company_name,
    () => lusha.company_name,
    () => ai.company_name,
    () => snovProspect.currentJob?.[0]?.companyName,
  );

  const industry = pick(
    () => lusha.company_industry,
    () => ai.company_industry,
    () => snovProspect.industry,
  );

  const headcount = pick(
    // Current Aimfox Lead sample does not provide clean company headcount.
    // Current Lusha sample also does not include headcount, but keep future-compatible fallbacks.
    () => lusha.company_size,
    () => ai.company_size,
    () => snovProspect.currentJob?.[0]?.size,
  );

  const leadReceived = pick(
    // Actual received reply date from Aimfox.
    () => aimfoxReply.reply_date,
    // Only if your previous normalize node calculated/stored the first sent message date.
    () => aimfoxReply.first_email_date,
  );

  const campaignName = pick(
    () => aimfoxReply.campaign_name,
    () => aimfoxLead.origin_campaign_name,
  );

  const messageTitle = pick(
    // LinkedIn/Aimfox message usually has no email subject.
    () => aimfoxReply.subject,
    () => aimfoxReply.flow_name,
    () => aimfoxReply.sequence_step_id
      ? `Step ${aimfoxReply.sequence_step_order || ''}`.trim()
      : '',
  );

  const messageNumber = pick(
    () => aimfoxReply.sequence_step_order,
  );

  const website = pick(
    () => lusha.company_domain,
    () => normalizeDomain(ai.company_website),
    () => getDomainFromEmail(email),
  );

  const qualification = 'MQL';

  const responseTime = pick(
    () => aimfoxReply.response_time_bucket,
  );

  const emailText = pick(
    () => aimfoxReply.reply_message,
  );

  const campaignId = pick(
    () => aimfoxReply.campaign_id,
    () => aimfoxLead.origin_campaign_id,
  );

  const linkedinUrl = pick(
    () => lusha.linkedin_url,
    () => aimfoxLead.linkedin_profile_url,
    () => aimfoxReply.linkedin_profile_url,
    () => linkedinFromPublicId(aimfoxLead.linkedin_public_identifier),
    () => linkedinFromPublicId(aimfoxReply.target_public_identifier),
    () => (snovProspect.social || []).find(s => s.type === 'linkedinProfile')?.link,
    () => ai.person_linkedin,
  );

  const country = pick(
    () => lusha.country,
    () => aimfoxLead.country,
    () => ai.lead_country,
    () => ai.company_country,
    () => snovProspect.country,
  );

  const values = [
    fullName,        // 0  FULL NAME
    jobTitle,        // 1  JOB TITLE
    email,           // 2  E-MAIL
    phoneNumber,     // 3  Phone Number
    phoneSource,     // 4  Phone Source
    companyName,     // 5  COMPANY NAME
    industry,        // 6  INDUSTRY
    headcount,       // 7  HEADCOUNT
    leadReceived,    // 8  LEAD RECEIVED — real Sheet date
    campaignName,    // 9  CAMPAIGN NAME
    messageTitle,    // 10 MESSAGE TITLE
    messageNumber,   // 11 MESSAGE #
    website,         // 12 WEBSITE
    qualification,   // 13 QUALIFICATION
    responseTime,    // 14 LEAD RESPONSE TIME
    '',              // 15
    '',              // 16
    '',              // 17
    '',              // 18
    '',              // 19
    '',              // 20
    emailText,       // 21 Mail from lead
    '',              // 22
    '',              // 23
    campaignId,      // 24 Campaign ID
    '',              // 25
    '',              // 26
    linkedinUrl,     // 27 LinkedIn URL
    country,         // 28 Country
  ];

  return JSON.stringify({
    requests: [
      {
        appendCells: {
          sheetId: Number(sheet.properties.sheetId),
          tableId: String(table.tableId),
          rows: [
            {
              values: values.map((value, index) => makeCell(value, index))
            }
          ],
          fields: 'userEnteredValue,userEnteredFormat.numberFormat'
        }
      }
    ]
  });
})() }}
